  "legal.privacy": "Informativa sulla privacy",
  "legal.terms": "Termini e condizioni",
  "legal.contactSupport": "Contatto e supporto",
  "legal.support": "Supporto",
  "legal.reportAbuse": "Segnala abuso",
  "legal.privacyRequests": "Richieste privacy",
  "legal.contactDescription": "Usa questa pagina per supporto, richieste privacy e segnalazioni di abuso.",
  "legal.contactSupportText": "Per aiuto con l'account, domande sul prodotto o feedback, scrivi a {email}.",
  "legal.reportAbuseText": "Se un profilo, messaggio, storia o comportamento sembra non sicuro, fuorviante o abusivo, includi l'URL del profilo, il contesto del messaggio e una breve spiegazione.",
  "legal.privacyRequestsText": "Per richieste privacy o cancellazione account, contatta il supporto dall'email collegata al tuo account così possiamo verificare la richiesta.",
  "legal.privacyDescription": "Questa pagina spiega i principali dati che Perfect AuPair usa per offrire matching tra au pair e famiglie ospitanti.",
  "legal.dataWeCollect": "Dati che raccogliamo",
  "legal.dataWeCollectText": "Raccogliamo informazioni account, dettagli profilo, foto, storie, profili salvati, messaggi e dati tecnici di base necessari per far funzionare il servizio in sicurezza. Alcune informazioni del profilo sono pubbliche per scelta, come nome visualizzato, posizione, età, bio, disponibilità, lingue e foto profilo.",
  "legal.dataNotPublic": "Dati che non mostriamo pubblicamente",
  "legal.dataNotPublicText": "Le pagine pubbliche di profilo e ricerca non devono mostrare dati privati come email, numero di telefono, indirizzo o data di nascita esatta. La data di nascita può essere usata internamente per calcolare l'età.",
  "legal.howWeUseData": "Come usiamo i dati",
  "legal.howWeUseDataText": "Usiamo i dati per creare account, mostrare profili, supportare la ricerca, consegnare messaggi, archiviare foto, prevenire abusi, proteggere la piattaforma e migliorare il servizio.",
  "legal.photosStoriesMessages": "Foto, storie e messaggi",
  "legal.photosStoriesMessagesText": "Le foto profilo fanno parte dei profili pubblici. Le storie sono temporanee e scadono dopo 24 ore. I messaggi sono privati tra i partecipanti alla conversazione, ma gli utenti dovrebbero evitare informazioni sensibili se non si fidano dell'altra persona.",
  "legal.serviceProviders": "Fornitori di servizi",
  "legal.serviceProvidersText": "Perfect AuPair usa fornitori di infrastruttura per hosting, autenticazione, database e storage. Questi fornitori trattano i dati necessari al funzionamento della piattaforma.",
  "legal.contactText": "Per richieste privacy, aiuto account o segnalazioni di abuso, contatta Perfect AuPair tramite i dettagli di supporto nella pagina Contatto.",
  "legal.termsDescription": "Questi termini descrivono le regole di base per usare Perfect AuPair.",
  "legal.useOfService": "Uso del servizio",
  "legal.useOfServiceText": "Perfect AuPair aiuta au pair e famiglie ospitanti a scoprirsi e contattarsi. Gli utenti sono responsabili delle informazioni fornite, delle persone contattate e delle decisioni prese fuori dalla piattaforma.",
  "legal.accountInformation": "Informazioni account",
  "legal.accountInformationText": "Accetti di fornire informazioni accurate e mantenere sicuro il tuo account. Non creare profili falsi, non impersonare altre persone e non caricare contenuti che non hai il diritto di usare.",
  "legal.safetyConduct": "Sicurezza e comportamento",
  "legal.safetyConductText": "Non molestare, minacciare, inviare spam, truffare o discriminare altri utenti. Non pubblicare contenuti illegali, espliciti, abusivi o fuorvianti. Perfect AuPair può rimuovere contenuti o limitare account per proteggere piattaforma e utenti.",
  "legal.platformRules": "Regole della piattaforma",
  "legal.ruleRealProfile": "Usa un profilo reale e non impersonare un'altra persona.",
  "legal.ruleRespect": "Tratta gli altri membri con rispetto; le molestie non sono consentite.",
  "legal.ruleNoScam": "Non truffare, inviare spam, fare pressione o fuorviare altri utenti.",
  "legal.ruleNoUnsafeContent": "Non caricare contenuti espliciti, illegali, abusivi o non sicuri.",
  "legal.rulePrivateInfo": "Non condividere informazioni private di qualcun altro senza consenso.",
  "legal.rulesConsequence": "La violazione di queste regole può portare alla rimozione di storie/foto, sospensione temporanea o ban permanente.",
  "legal.auPairRequirements": "Requisiti au pair",
  "legal.auPairRequirementsText": "Le regole au pair dipendono da paese, visto, età, lingua, assicurazione e requisiti legali locali. Gli utenti devono verificare i requisiti applicabili prima di prendere accordi.",
  "legal.messagesContactDetails": "Messaggi e contatti",
  "legal.messagesContactDetailsText": "Gli utenti possono scambiarsi contatti nei messaggi. Fai attenzione quando condividi informazioni personali e segnala comportamenti sospetti.",
  "legal.noPaymentTerms": "Nessun termine di pagamento",
  "legal.noPaymentTermsText": "Perfect AuPair è attualmente gratuito. Funzionalità a pagamento potranno essere introdotte più tardi solo se la strategia del prodotto cambia.",
  "maintenance.title": "Manutenzione",
  "maintenance.description": "Perfect AuPair è temporaneamente non disponibile mentre risolviamo un problema tecnico.",
  "maintenance.soonTitle": "Torneremo online a breve.",
  "maintenance.longDescription": "Stiamo risolvendo un problema tecnico e lavorando per ripristinare l’accesso il prima possibile. Riprova tra poco.",
