  "legal.privacy": "Datenschutzerklärung",
  "legal.terms": "Allgemeine Geschäftsbedingungen",
  "legal.contactSupport": "Kontakt und Support",
  "legal.support": "Support",
  "legal.reportAbuse": "Missbrauch melden",
  "legal.privacyRequests": "Datenschutzanfragen",
  "legal.contactDescription": "Nutze diese Seite für Support, Datenschutzanfragen und Missbrauchsmeldungen.",
  "legal.contactSupportText": "Für Hilfe zum Konto, Produktfragen oder Feedback schreibe an {email}.",
  "legal.reportAbuseText": "Wenn ein Profil, eine Nachricht, eine Story oder ein Verhalten unsicher, irreführend oder missbräuchlich wirkt, füge die Profil-URL, den Nachrichtenkontext und eine kurze Erklärung hinzu.",
  "legal.privacyRequestsText": "Für Datenschutz- oder Kontolöschanfragen kontaktiere den Support über die mit deinem Konto verbundene E-Mail-Adresse, damit die Anfrage geprüft werden kann.",
  "legal.privacyDescription": "Diese Seite erklärt die wichtigsten Daten, die Perfect AuPair für das Matching von Au-pairs und Gastfamilien nutzt.",
  "legal.dataWeCollect": "Daten, die wir erheben",
  "legal.dataWeCollectText": "Wir erheben Kontoinformationen, Profildetails, Fotos, Stories, gespeicherte Profile, Nachrichten und grundlegende technische Daten, die für einen sicheren Betrieb nötig sind. Einige Profildaten sind bewusst öffentlich, etwa Anzeigename, Ort, Alter, Bio, Verfügbarkeit, Sprachen und Profilfotos.",
  "legal.dataNotPublic": "Daten, die wir nicht öffentlich zeigen",
  "legal.dataNotPublicText": "Öffentliche Profil- und Suchseiten sollen keine privaten Kontodaten wie E-Mail-Adresse, Telefonnummer, Straße oder exaktes Geburtsdatum anzeigen. Das Geburtsdatum kann intern zur Altersberechnung genutzt werden.",
  "legal.howWeUseData": "Wie wir Daten nutzen",
  "legal.howWeUseDataText": "Wir nutzen Daten, um Konten zu erstellen, Profile anzuzeigen, Suche zu unterstützen, Nachrichten zuzustellen, Fotos zu speichern, Missbrauch zu verhindern, die Plattform zu schützen und den Service zu verbessern.",
  "legal.photosStoriesMessages": "Fotos, Stories und Nachrichten",
  "legal.photosStoriesMessagesText": "Profilfotos sind Teil öffentlicher Profile. Stories sind temporär und laufen nach 24 Stunden ab. Nachrichten sind privat zwischen Gesprächsteilnehmern, aber Nutzer sollten sensible Informationen nur teilen, wenn sie der anderen Person vertrauen.",
  "legal.serviceProviders": "Dienstleister",
  "legal.serviceProvidersText": "Perfect AuPair nutzt Infrastruktur-Dienstleister für Hosting, Authentifizierung, Datenbank und Speicher. Diese Anbieter verarbeiten Daten, soweit es für den Betrieb der Plattform nötig ist.",
  "legal.contactText": "Für Datenschutzanfragen, Kontohilfe oder Missbrauchsmeldungen kontaktiere Perfect AuPair über die Supportdetails auf der Kontaktseite.",
  "legal.termsDescription": "Diese Bedingungen beschreiben die Grundregeln für die Nutzung von Perfect AuPair.",
  "legal.useOfService": "Nutzung des Dienstes",
  "legal.useOfServiceText": "Perfect AuPair hilft Au-pairs und Gastfamilien, einander zu entdecken und zu kontaktieren. Nutzer sind verantwortlich für ihre Angaben, die kontaktierten Personen und Entscheidungen außerhalb der Plattform.",
  "legal.accountInformation": "Kontoinformationen",
  "legal.accountInformationText": "Du stimmst zu, korrekte Informationen bereitzustellen und dein Konto sicher zu halten. Erstelle keine Fake-Profile, gib dich nicht als andere Person aus und lade keine Inhalte hoch, zu deren Nutzung du nicht berechtigt bist.",
  "legal.safetyConduct": "Sicherheit und Verhalten",
  "legal.safetyConductText": "Belästige, bedrohe, spamme, betrüge oder diskriminiere keine anderen Nutzer. Poste keine illegalen, expliziten, missbräuchlichen oder irreführenden Inhalte. Perfect AuPair kann Inhalte entfernen oder Konten einschränken, um Plattform und Nutzer zu schützen.",
  "legal.platformRules": "Plattformregeln",
  "legal.ruleRealProfile": "Nutze ein echtes Profil und gib dich nicht als andere Person aus.",
  "legal.ruleRespect": "Behandle andere Mitglieder respektvoll; Belästigung ist nicht erlaubt.",
  "legal.ruleNoScam": "Betrüge, spamme, dränge oder täusche andere Nutzer nicht.",
  "legal.ruleNoUnsafeContent": "Lade keine expliziten, illegalen, missbräuchlichen oder unsicheren Inhalte hoch.",
  "legal.rulePrivateInfo": "Teile keine privaten Informationen anderer Personen ohne Zustimmung.",
  "legal.rulesConsequence": "Verstöße können zur Entfernung von Stories/Fotos, temporärer Sperre oder permanentem Bann führen.",
  "legal.auPairRequirements": "Au-pair-Anforderungen",
  "legal.auPairRequirementsText": "Au-pair-Regeln hängen von Land, Visum, Alter, Sprache, Versicherung und lokalen rechtlichen Anforderungen ab. Nutzer müssen die für sie geltenden Anforderungen prüfen, bevor sie Vereinbarungen treffen.",
  "legal.messagesContactDetails": "Nachrichten und Kontaktdaten",
  "legal.messagesContactDetailsText": "Nutzer dürfen Kontaktdaten in Nachrichten austauschen. Sei vorsichtig beim Teilen persönlicher Informationen und melde verdächtiges Verhalten.",
  "legal.noPaymentTerms": "Keine Zahlungsbedingungen",
  "legal.noPaymentTermsText": "Perfect AuPair ist derzeit kostenlos. Bezahlte Funktionen können später nur eingeführt werden, wenn sich die Produktstrategie ändert.",
  "maintenance.title": "Wartung",
  "maintenance.description": "Perfect AuPair ist vorübergehend nicht verfügbar, während wir ein technisches Problem beheben.",
  "maintenance.soonTitle": "Wir sind in Kürze wieder da.",
  "maintenance.longDescription": "Wir beheben derzeit ein technisches Problem und arbeiten daran, den Zugang so schnell wie möglich wiederherzustellen. Bitte versuche es in Kürze erneut.",
  "saved.eyebrow": "Gespeichert",
  "saved.title": "Gespeicherte Profile",
  "saved.description": "Profile, die du für später gespeichert hast.",
  "saved.loadFailed": "Gespeicherte Profile konnten nicht geladen werden: {message}",
