  "notifications.reportActionBody": "Merci pour votre signalement. Nous avons examiné l'interaction et pris des mesures conformément à nos règles de sécurité. Pour des raisons de confidentialité et de sécurité, nous ne pouvons pas communiquer la mesure exacte prise sur le compte. Sur Perfect AuPair, vous pouvez signaler un membre depuis son profil avec « Signaler ce profil », ou depuis le menu de la conversation avec « Signaler le profil ». Les signalements envoyés ainsi arrivent directement dans notre tableau de modération.",
