  "legal.dataWeCollect": "Données que nous collectons",
  "legal.dataWeCollectText": "Nous collectons des informations de compte, des détails de profil, des photos, des histoires, des profils enregistrés, des messages et des données techniques de base nécessaires pour exécuter le service en toute sécurité. Certaines informations de profil sont publiques de par leur conception, telles que le nom d'affichage, l'emplacement, l'âge, la biographie, la disponibilité, les langues et les photos de profil.",
