  "legal.privacy": "Privacybeleid",
  "legal.terms": "Algemene voorwaarden",
  "legal.contactSupport": "Contact en ondersteuning",
  "legal.support": "Steun",
  "legal.reportAbuse": "Misbruik melden",
  "legal.privacyRequests": "Privacyverzoeken",
  "legal.contactDescription": "Gebruik deze pagina voor ondersteuning, privacyverzoeken en misbruikmeldingen.",
  "legal.contactSupportText": "Voor accounthulp, productvragen of feedback kunt u een e-mail sturen naar {email}.",
  "legal.reportAbuseText": "Als een profiel, bericht, verhaal of gebruikersgedrag er onveilig, misleidend of beledigend uitziet, neem dan de profiel-URL, berichtcontext en een korte uitleg op in uw rapport.",
  "legal.privacyRequestsText": "Voor verzoeken om privacy of accountverwijdering kunt u contact opnemen met de ondersteuning vanaf het e-mailadres dat aan uw account is gekoppeld, zodat het verzoek kan worden geverifieerd.",
  "legal.privacyDescription": "Op deze pagina worden de belangrijkste gegevens uitgelegd die Perfect AuPair gebruikt om au pair en gastgezin te matchen.",
  "legal.dataWeCollect": "Gegevens die we verzamelen",
  "legal.dataWeCollectText": "We verzamelen accountinformatie, profielgegevens, foto's, verhalen, opgeslagen profielen, berichten en technische basisgegevens die nodig zijn om de service veilig uit te voeren. Sommige profielinformatie is openbaar, zoals weergavenaam, locatie, leeftijd, biografie, beschikbaarheid, talen en profielfoto's.",
  "legal.dataNotPublic": "Gegevens die wij niet openbaar tonen",
  "legal.dataNotPublicText": "Op openbare profiel- en zoekpagina's mogen geen privéaccountgegevens worden weergegeven, zoals e-mailadres, telefoonnummer, adres, postcode of exacte geboortedatum. Geboortedatum kan intern worden gebruikt om de leeftijd te berekenen.",
  "legal.howWeUseData": "Hoe wij gegevens gebruiken",
  "legal.howWeUseDataText": "We gebruiken gegevens om accounts aan te maken, profielen weer te geven, zoeken te ondersteunen, berichten te bezorgen, foto's op te slaan, misbruik te voorkomen, het platform te beschermen en de service te verbeteren.",
  "legal.photosStoriesMessages": "Foto's, verhalen en berichten",
  "legal.photosStoriesMessagesText": "Profielfoto's maken deel uit van openbare profielen. Stories zijn tijdelijk en vervallen na 24 uur. Berichten zijn privé tussen gespreksdeelnemers, maar gebruikers moeten vermijden gevoelige informatie te delen tenzij ze de andere persoon vertrouwen.",
  "legal.serviceProviders": "Dienstverleners",
  "legal.serviceProvidersText": "Perfect AuPair maakt gebruik van infrastructuurproviders voor hosting, authenticatie, database en opslag. Deze providers verwerken gegevens als dat nodig is om het platform te laten functioneren.",
  "legal.contactText": "Voor privacyverzoeken, accounthulp of misbruikrapporten kunt u contact opnemen met Perfect AuPair via de ondersteuningsgegevens op de contactpagina.",
  "legal.termsDescription": "Deze voorwaarden beschrijven de basisregels voor het gebruik van Perfect AuPair.",
  "legal.useOfService": "Gebruik van de dienst",
  "legal.useOfServiceText": "Perfect AuPair helpt au pairs en gastgezinnen elkaar te ontdekken en met elkaar in contact te komen. Gebruikers zijn verantwoordelijk voor de informatie die zij verstrekken, de mensen waarmee zij contact opnemen en de beslissingen die zij buiten het platform nemen.",
  "legal.accountInformation": "Accountinformatie",
  "legal.accountInformationText": "U gaat ermee akkoord nauwkeurige informatie te verstrekken en uw account veilig te houden. Maak geen nepprofielen aan, doe je niet voor als iemand anders en upload geen inhoud waarvoor je geen gebruiksrecht hebt.",
  "legal.safetyConduct": "Veiligheid en gedrag",
  "legal.safetyConductText": "Andere gebruikers niet lastigvallen, bedreigen, spammen, oplichten of discrimineren. Plaats geen illegale, expliciete, beledigende of misleidende inhoud. Perfect AuPair kan inhoud verwijderen of accounts beperken om het platform en zijn gebruikers te beschermen.",
  "legal.platformRules": "Platformregels",
  "legal.ruleRealProfile": "Gebruik een echt profiel en doe u niet voor als iemand anders.",
  "legal.ruleRespect": "Behandel andere leden respectvol; intimidatie is niet toegestaan.",
  "legal.ruleNoScam": "Andere gebruikers niet oplichten, spammen, onder druk zetten of misleiden.",
  "legal.ruleNoUnsafeContent": "Upload geen expliciete, illegale, beledigende of onveilige inhoud.",
  "legal.rulePrivateInfo": "Deel de privégegevens van iemand anders niet zonder toestemming.",
  "legal.rulesConsequence": "Het overtreden van deze regels kan leiden tot het verwijderen van verhalen/foto's, tijdelijke opschorting of een permanente verbanning.",
  "legal.auPairRequirements": "Au pair-vereisten",
  "legal.auPairRequirementsText": "De regels voor au pairs zijn afhankelijk van het land, het visumtype, de leeftijd, de taal, de verzekering en de lokale wettelijke vereisten. Het is de verantwoordelijkheid van gebruikers om vóór het maken van afspraken te controleren welke eisen voor hun situatie gelden.",
  "legal.messagesContactDetails": "Berichten en contactgegevens",
  "legal.messagesContactDetailsText": "Gebruikers kunnen contactgegevens uitwisselen in berichten. Wees voorzichtig met het delen van persoonlijke informatie en meld verdacht gedrag.",
  "legal.noPaymentTerms": "Geen betalingsvoorwaarden",
  "legal.noPaymentTermsText": "Perfect AuPair is momenteel gratis te gebruiken. Betaalde functies kunnen alleen later worden geïntroduceerd als de productstrategie verandert.",
  "maintenance.title": "Onderhoud",
  "maintenance.description": "Perfect AuPair is tijdelijk niet beschikbaar terwijl we een technisch probleem oplossen.",
  "maintenance.soonTitle": "We zijn zo snel mogelijk terug.",
  "maintenance.longDescription": "We lossen momenteel een technisch probleem op en werken eraan om de toegang zo snel mogelijk te herstellen. Probeer het over enkele ogenblikken opnieuw.",
