const dictionaries = {
  en,
  es,
  de,
  fr,
  nl,
  it,
} satisfies Record<LanguageCode, Dictionary>;

export const DICTIONARIES: Record<LanguageCode, Dictionary> = dictionaries;

export function isI18nKey(value: string): value is I18nKey {
  return Object.prototype.hasOwnProperty.call(en, value);
}

export function getDictionary(locale: LanguageCode): Dictionary {
  return DICTIONARIES[locale] ?? DICTIONARIES[DEFAULT_LANGUAGE];
}

function interpolate(template: string, values: TranslationValues = {}) {
  return template.replace(/\{(\w+)\}/g, (match, key) => {
    const value = values[key];
    return value === undefined ? match : String(value);
  });
}

export type Translate = (key: I18nKey, values?: TranslationValues) => string;

export function createTranslator(locale: LanguageCode): Translate {
  const dictionary = getDictionary(locale);

  return (key, values) => interpolate(dictionary[key] ?? en[key], values);
}

export function translate(locale: LanguageCode, key: I18nKey, values?: TranslationValues) {
  return createTranslator(locale)(key, values);
}

export function formatAccountType(type: "au_pair" | "family" | string | null | undefined, locale: LanguageCode) {
  const t = createTranslator(locale);
  return type === "family" ? t("common.hostFamily") : t("common.auPair");
}

export function formatProfileBadge(type: "au_pair" | "family" | string | null | undefined, locale: LanguageCode) {
  return formatProfileBadgeWithTranslator(type, createTranslator(locale));
}

export function formatProfileActivityStatus(
  status: string | null | undefined,
  locale: LanguageCode,
) {
  return formatProfileActivityStatusWithTranslator(
    status,
    createTranslator(locale),
  );
}

export function formatPhotoCount(count: number, locale: LanguageCode) {
  const t = createTranslator(locale);
  return t(count === 1 ? "format.photo.one" : "format.photo.other", { count });
}

export function formatAge(age: number, locale: LanguageCode) {
  return createTranslator(locale)("format.age", { age });
}

export function formatGeneratedFamilyDisplayName(
  name: string,
  locale: LanguageCode,
) {
  return formatGeneratedFamilyDisplayNameWithTranslator(
    name,
    createTranslator(locale),
  );
}

export function formatFamilyDisplayName(
  value: string | null | undefined,
  locale: LanguageCode,
) {
  return formatFamilyDisplayNameWithTranslator(value, createTranslator(locale));
}

export function formatFamilyStoryDisplayName(
  value: string | null | undefined,
  locale: LanguageCode,
) {
  return formatFamilyStoryDisplayNameWithTranslator(
    value,
    createTranslator(locale),
  );
}

export function formatDuration(
  locale: LanguageCode,
  min?: number | null,
  max?: number | null,
) {
  const t = createTranslator(locale);
  if (min && max) {
    if (min === max) {
      return t(min === 1 ? "format.month.one" : "format.month.other", {
        count: min,
      });
    }

    return t("format.duration.range", { min, max });
  }
  if (min) return t("format.duration.min", { min });
  if (max) return t("format.duration.max", { max });

  return t("format.duration.notSet");
}

export function formatAllowance(
  amount?: number | null,
  currency?: string | null,
  locale: LanguageCode = DEFAULT_LANGUAGE,
) {
  if (!amount || amount <= 0 || !currency) return null;
  if (!["EUR", "GBP", "USD"].includes(currency)) return null;

  const formattedAmount = new Intl.NumberFormat(getLocaleTag(locale), {
    style: "currency",
    currency,
    maximumFractionDigits: 0,
  }).format(amount);

  return createTranslator(locale)("format.allowancePerMonth", {
    amount: formattedAmount,
  });
}

export function formatMonth(value: string | null | undefined, locale: LanguageCode) {
  if (!value) return null;
  const date = new Date(`${value}T00:00:00.000Z`);
  if (Number.isNaN(date.getTime())) return null;

  return new Intl.DateTimeFormat(getLocaleTag(locale), {
    month: "short",
    year: "numeric",
    timeZone: "UTC",
  }).format(date);
}

export function formatStartWindow(
  locale: LanguageCode,
  from?: string | null,
  to?: string | null,
) {
  const t = createTranslator(locale);
  const normalizedWindow = normalizeStartMonthRange({ from, to });
  const normalizedFrom = normalizedWindow.startFrom
    ? `${normalizedWindow.startFrom}-01`
    : null;
  const normalizedTo = normalizedWindow.startTo
    ? `${normalizedWindow.startTo}-01`
    : null;
  const start = formatMonth(normalizedFrom, locale);
  const end = formatMonth(normalizedTo, locale);

  if (start && end) return start === end ? start : `${start} - ${end}`;
  if (start) return t("format.start.from", { date: start });
  if (end) return t("format.start.until", { date: end });

  return t("format.start.notSet");
}

export function formatGender(value: string | null | undefined, locale: LanguageCode) {
  return formatGenderWithTranslator(value, createTranslator(locale));
}

export function formatSmoking(value: string | null | undefined, locale: LanguageCode) {
  return formatSmokingWithTranslator(value, createTranslator(locale));
}

